// Altere somente este objeto para simular cada mensagem do mesmo contato.
const sample={senderId:'5511999999999@s.whatsapp.net', messageId:'lab-mensagem-001', text:'Quasimoto', senderName:'Contato de laboratório'};
const norm=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const t=norm(sample.text);
let category='outros';
if (/\b(oi|ola|opa|bom dia|boa tarde|boa noite)\b/.test(t))category='saudacao';
else if (/\b(mf ?doom|mfdu|quasimoto|dichavador|tchavador|pracinha)\b/.test(t))category='produto';
else if (/\b(catalogo|catalog)\b/.test(t))category='catalogo';
else if (/\b(preco|valor|quanto|custa)\b/.test(t))category='preco';
else if (/\b(entrega|frete|cep|envio)\b/.test(t))category='entrega';
else if (/\b(pedido|rastreio|compra)\b/.test(t))category='pedido';
const handoffRequested=false; // Mude para true só ao simular uma transferência humana.
return [{json:{instance:'umdoislab',isClientMessage:true,isGroup:false,
senderId:sample.senderId,senderName:sample.senderName,messageId:sample.messageId,
messageText:sample.text,category,summary:'Laboratório v1.5 — '+category,
handoffRequested}}];

const result=$input.first()?.json;
if (!result || typeof result.action!=='string' || !['auto','handoff','offer_choice','resume','silent','ignore'].includes(result.action))throw Error('Central indisponível ou resposta inválida; bloquear.');
const incoming=$('Evento de teste e classificação').first().json;
const action=result.action;
if (['silent','ignore'].includes(action))return [{json:{...incoming,action,shouldSend:false,reason:'Atendimento humano ou evento repetido'}}];
let kind='normal',text='',reason='';
if(action==='handoff'){kind='handoff';reason='Transferência para humano (texto definido no servidor)';}
else if(action==='offer_choice'){kind='choice';reason='Perguntar 1 aguardar / 2 continuar (texto definido no servidor)';}
else if(action==='resume'){text='Certo! Podemos continuar pelo atendimento automático. 😊 O que você gostaria de saber?';reason='Cliente pediu explicitamente para continuar';}
else {
 const replies={
  saudacao:'Oi! Tudo bem? 😊 Como posso ajudar aqui na Umdoislab?',
  catalogo:'Você pode conhecer a Umdoislab em https://umdoislab.com.br/ 😊 Quer procurar algum produto específico?',
  produto:'Posso te ajudar a localizar esse produto. Qual modelo ou informação você procura? Não vou informar preço sem consultar o catálogo.',
  preco:'Qual produto você quer consultar? Assim podemos confirmar o valor correto.',
  entrega:'Para conferir a entrega, me diga o CEP e o produto desejado, por favor.',
  pedido:'Posso encaminhar sua dúvida sobre pedido para atendimento pessoal. Pode descrever o que aconteceu?'
 };
 text=replies[incoming.category]||'Pode me dizer o nome do produto ou qual informação você procura?';
 kind=incoming.category==='outros'?'fallback':'normal';
 reason='Resposta de laboratório, sem preço ou estoque inventado';
}
return [{json:{instance:incoming.instance,senderId:incoming.senderId,messageId:incoming.messageId,
kind,text,action,shouldSend:true,reason}}];
